INSERT INTO kleron.cards (id, name, number, suit, image_url, upright_meaning, reversed_meaning, keywords, description) VALUES

-- Major Arcana
('major-00','The Fool',0,'major','/cards/major-00.jpg','New beginnings, innocence, spontaneity, free spirit.','Recklessness, risk-taking, naivety, poor judgement.',ARRAY['beginnings','innocence','adventure','potential'],'The Fool steps off the cliff with total trust, unaware or unbothered by the drop below.'),
('major-01','The Magician',1,'major','/cards/major-01.jpg','Willpower, skill, resourcefulness, concentrated action.','Manipulation, trickery, wasted talent, poor planning.',ARRAY['skill','willpower','manifestation','action'],'The Magician channels all four elements, turning intention into reality.'),
('major-02','The High Priestess',2,'major','/cards/major-02.jpg','Intuition, inner knowledge, mystery, the unconscious.','Hidden agendas, secrets kept from you, disconnection from intuition.',ARRAY['intuition','mystery','subconscious','stillness'],'She sits between two pillars guarding the veil between worlds.'),
('major-03','The Empress',3,'major','/cards/major-03.jpg','Fertility, abundance, nurturing, sensuality, nature.','Creative block, dependence, smothering, neglect.',ARRAY['abundance','nurturing','fertility','nature'],'The Empress embodies the creative force of nature in full bloom.'),
('major-04','The Emperor',4,'major','/cards/major-04.jpg','Authority, structure, stability, fatherhood, leadership.','Domination, rigidity, control issues, inflexibility.',ARRAY['authority','structure','stability','power'],'He rules through order and discipline, providing protection through structure.'),
('major-05','The Hierophant',5,'major','/cards/major-05.jpg','Tradition, institutions, spiritual wisdom, conformity.','Dogma, rebellion, subversiveness, questioning norms.',ARRAY['tradition','wisdom','conformity','belief'],'The bridge between the sacred and the earthly, he transmits ancient wisdom.'),
('major-06','The Lovers',6,'major','/cards/major-06.jpg','Love, harmony, relationships, choices, alignment of values.','Disharmony, misalignment, bad choices, conflict.',ARRAY['love','union','choice','values'],'More than romance — a card of choices made from the heart.'),
('major-07','The Chariot',7,'major','/cards/major-07.jpg','Control, willpower, victory, determination, discipline.','Lack of direction, aggression, powerlessness.',ARRAY['control','victory','determination','drive'],'Opposing forces harnessed and driven forward by sheer will.'),
('major-08','Strength',8,'major','/cards/major-08.jpg','Courage, patience, inner strength, compassion over force.','Self-doubt, weakness, insecurity, raw emotion.',ARRAY['courage','patience','compassion','fortitude'],'She tames the lion not with force but with gentle persistence.'),
('major-09','The Hermit',9,'major','/cards/major-09.jpg','Introspection, solitude, inner guidance, seeking truth.','Isolation, loneliness, withdrawal, losing your way.',ARRAY['solitude','introspection','guidance','wisdom'],'He holds the lantern not to light the world, but to illuminate the next step.'),
('major-10','Wheel of Fortune',10,'major','/cards/major-10.jpg','Cycles, fate, turning points, luck, destiny.','Bad luck, resistance to change, breaking cycles.',ARRAY['fate','cycles','luck','turning point'],'The wheel turns — what rises must fall, what falls must rise.'),
('major-11','Justice',11,'major','/cards/major-11.jpg','Fairness, truth, law, cause and effect, accountability.','Unfairness, dishonesty, lack of accountability.',ARRAY['justice','truth','fairness','law'],'The scales do not lie; every action meets its equal consequence.'),
('major-12','The Hanged Man',12,'major','/cards/major-12.jpg','Suspension, letting go, new perspective, sacrifice.','Delays, resistance, indecision, stalling.',ARRAY['surrender','perspective','pause','sacrifice'],'He chose to hang; the pause is willing, the perspective transformed.'),
('major-13','Death',13,'major','/cards/major-13.jpg','Endings, transformation, transition, letting go.','Resistance to change, stagnation, inability to move on.',ARRAY['transformation','endings','transition','change'],'Not literal death — the inexorable end of one chapter so another may begin.'),
('major-14','Temperance',14,'major','/cards/major-14.jpg','Balance, moderation, patience, purpose, flowing between extremes.','Imbalance, excess, lack of long-term vision.',ARRAY['balance','moderation','patience','alchemy'],'She pours water between cups endlessly — the art of perfect flow.'),
('major-15','The Devil',15,'major','/cards/major-15.jpg','Bondage, addiction, materialism, shadow self, patterns.','Freedom, release, reclaiming power, breaking chains.',ARRAY['bondage','addiction','shadow','materialism'],'The chains are loose — the figures could leave, but they stay.'),
('major-16','The Tower',16,'major','/cards/major-16.jpg','Sudden change, upheaval, chaos, revelation, awakening.','Avoiding disaster, fear of change, delaying the inevitable.',ARRAY['upheaval','chaos','revelation','destruction'],'Lightning strikes the crown of false certainty. What falls needed to fall.'),
('major-17','The Star',17,'major','/cards/major-17.jpg','Hope, renewal, serenity, inspiration, faith.','Hopelessness, despair, disconnection, lack of faith.',ARRAY['hope','renewal','serenity','inspiration'],'After the Tower, she pours water freely — healing flows again.'),
('major-18','The Moon',18,'major','/cards/major-18.jpg','Illusion, fear, the unconscious, confusion, anxiety.','Clarity emerging, releasing fears, misunderstanding lifted.',ARRAY['illusion','fear','subconscious','mystery'],'The path between the towers is real but the light distorts everything.'),
('major-19','The Sun',19,'major','/cards/major-19.jpg','Joy, success, vitality, confidence, radiance.','Temporary sadness, lack of clarity, blocked joy.',ARRAY['joy','success','vitality','clarity'],'The child dances in the sun — unguarded, triumphant, fully alive.'),
('major-20','Judgement',20,'major','/cards/major-20.jpg','Reckoning, reflection, awakening, absolution, calling.','Self-doubt, refusal to hear the call, harsh self-judgement.',ARRAY['reckoning','awakening','reflection','calling'],'The trumpet sounds. Those who are ready rise to answer.'),
('major-21','The World',21,'major','/cards/major-21.jpg','Completion, integration, accomplishment, wholeness, travel.','Incompleteness, shortcuts, loose ends, stagnation.',ARRAY['completion','wholeness','achievement','integration'],'She dances inside the wreath — the cycle complete, everything in balance.'),

-- Wands
('wands-ace','Ace of Wands',1,'wands','/cards/wands-ace.jpg','New creative spark, inspiration, potential, birth of an idea.','Delays, creative block, lack of passion.',ARRAY['spark','inspiration','potential','action'],''),
('wands-02','Two of Wands',2,'wands','/cards/wands-02.jpg','Planning, future vision, discovery, bold ambition.','Fear of the unknown, lack of planning, playing it safe.',ARRAY['planning','ambition','vision','expansion'],''),
('wands-03','Three of Wands',3,'wands','/cards/wands-03.jpg','Progress, expansion, foresight, looking ahead.','Obstacles, delays, frustration with slow progress.',ARRAY['progress','expansion','foresight','enterprise'],''),
('wands-04','Four of Wands',4,'wands','/cards/wands-04.jpg','Celebration, harmony, homecoming, community.','Lack of support, instability, conflict at home.',ARRAY['celebration','harmony','community','milestone'],''),
('wands-05','Five of Wands',5,'wands','/cards/wands-05.jpg','Conflict, competition, tension, clashing perspectives.','Avoiding conflict, seeking resolution, inner tension.',ARRAY['conflict','competition','tension','disagreement'],''),
('wands-06','Six of Wands',6,'wands','/cards/wands-06.jpg','Victory, public recognition, success, confidence.','Ego, fall from grace, lack of recognition.',ARRAY['victory','recognition','pride','success'],''),
('wands-07','Seven of Wands',7,'wands','/cards/wands-07.jpg','Perseverance, defensiveness, holding your ground.','Giving up, overwhelmed, ceding ground.',ARRAY['perseverance','challenge','defense','conviction'],''),
('wands-08','Eight of Wands',8,'wands','/cards/wands-08.jpg','Swift movement, rapid action, travel, momentum.','Delays, frustration, miscommunication.',ARRAY['speed','momentum','swiftness','communication'],''),
('wands-09','Nine of Wands',9,'wands','/cards/wands-09.jpg','Resilience, persistence, close to the end, courage.','Stubbornness, exhaustion, refusing to yield.',ARRAY['resilience','persistence','guarded','stamina'],''),
('wands-10','Ten of Wands',10,'wands','/cards/wands-10.jpg','Burden, extra responsibility, hard work, completion.','Unable to delegate, collapse under pressure.',ARRAY['burden','responsibility','overextension','completion'],''),
('wands-page','Page of Wands',11,'wands','/cards/wands-page.jpg','Enthusiasm, exploration, discovery, free spirit.','Lack of direction, hasty, scattered energy.',ARRAY['enthusiasm','exploration','potential','messenger'],''),
('wands-knight','Knight of Wands',12,'wands','/cards/wands-knight.jpg','Energy, passion, adventure, fearlessness.','Recklessness, anger, impulsiveness.',ARRAY['passion','adventure','energy','impulsive'],''),
('wands-queen','Queen of Wands',13,'wands','/cards/wands-queen.jpg','Confidence, courage, independence, social warmth.','Demanding, selfish, insecure, pushy.',ARRAY['confidence','independence','warmth','courage'],''),
('wands-king','King of Wands',14,'wands','/cards/wands-king.jpg','Natural leadership, vision, entrepreneur, honor.','Impulsive, domineering, vain, ruthless.',ARRAY['leadership','vision','charisma','entrepreneur'],''),

-- Cups
('cups-ace','Ace of Cups',1,'cups','/cards/cups-ace.jpg','New love, emotional beginning, compassion, creativity.','Emotional repression, emptiness, blocked feelings.',ARRAY['love','emotion','compassion','creativity'],''),
('cups-02','Two of Cups',2,'cups','/cards/cups-02.jpg','Unified love, partnership, mutual attraction.','Imbalance in a relationship, broken trust.',ARRAY['partnership','unity','attraction','connection'],''),
('cups-03','Three of Cups',3,'cups','/cards/cups-03.jpg','Celebration, friendship, collaboration, joy.','Gossip, overindulgence, social isolation.',ARRAY['friendship','celebration','community','joy'],''),
('cups-04','Four of Cups',4,'cups','/cards/cups-04.jpg','Contemplation, apathy, missed opportunities.','New enthusiasm, awareness, re-engagement.',ARRAY['boredom','apathy','contemplation','withdrawal'],''),
('cups-05','Five of Cups',5,'cups','/cards/cups-05.jpg','Loss, grief, disappointment, focusing on what is gone.','Moving on, acceptance, finding peace after loss.',ARRAY['loss','grief','regret','disappointment'],''),
('cups-06','Six of Cups',6,'cups','/cards/cups-06.jpg','Nostalgia, childhood memories, innocence, reunion.','Living in the past, naivety, lost childhood.',ARRAY['nostalgia','memories','innocence','reunion'],''),
('cups-07','Seven of Cups',7,'cups','/cards/cups-07.jpg','Illusion, fantasy, wishful thinking, many choices.','Clarity, making choices, facing reality.',ARRAY['fantasy','illusion','choice','wishful thinking'],''),
('cups-08','Eight of Cups',8,'cups','/cards/cups-08.jpg','Withdrawal, walking away, seeking deeper meaning.','Trying one more time, fear of moving on.',ARRAY['withdrawal','abandonment','deeper meaning','journey'],''),
('cups-09','Nine of Cups',9,'cups','/cards/cups-09.jpg','Contentment, satisfaction, wishes fulfilled, wellbeing.','Greed, dissatisfaction, materialism.',ARRAY['contentment','wishes','satisfaction','pleasure'],''),
('cups-10','Ten of Cups',10,'cups','/cards/cups-10.jpg','Harmony, family, lasting happiness, alignment.','Broken home, conflict, misaligned values.',ARRAY['harmony','family','happiness','fulfillment'],''),
('cups-page','Page of Cups',11,'cups','/cards/cups-page.jpg','Creative opportunities, curiosity, intuitive messages.','Emotional immaturity, insecurity, disappointment.',ARRAY['creativity','intuition','curiosity','sensitivity'],''),
('cups-knight','Knight of Cups',12,'cups','/cards/cups-knight.jpg','Romance, charm, imagination, following the heart.','Unrealistic, jealous, moodiness.',ARRAY['romance','charm','idealism','imagination'],''),
('cups-queen','Queen of Cups',13,'cups','/cards/cups-queen.jpg','Compassion, nurturing, emotional security, intuition.','Insecurity, co-dependency, emotional manipulation.',ARRAY['compassion','nurturing','intuition','empathy'],''),
('cups-king','King of Cups',14,'cups','/cards/cups-king.jpg','Emotional balance, generosity, diplomacy, wisdom.','Emotional manipulation, moodiness, coldness.',ARRAY['emotional balance','diplomacy','wisdom','generosity'],''),

-- Swords
('swords-ace','Ace of Swords',1,'swords','/cards/swords-ace.jpg','Clarity, breakthrough, truth, new idea, sharp mind.','Confusion, chaos, clouded judgement.',ARRAY['clarity','truth','breakthrough','intellect'],''),
('swords-02','Two of Swords',2,'swords','/cards/swords-02.jpg','Indecision, stalemate, blocked emotions, avoiding truth.','Indecision broken, information revealed, confusion.',ARRAY['indecision','stalemate','avoidance','blocked'],''),
('swords-03','Three of Swords',3,'swords','/cards/swords-03.jpg','Heartbreak, grief, sorrow, emotional pain.','Recovery, forgiveness, moving through pain.',ARRAY['heartbreak','sorrow','grief','loss'],''),
('swords-04','Four of Swords',4,'swords','/cards/swords-04.jpg','Rest, restoration, contemplation, recovering.','Restlessness, burnout, recovery stalled.',ARRAY['rest','recovery','contemplation','stillness'],''),
('swords-05','Five of Swords',5,'swords','/cards/swords-05.jpg','Conflict, tension, defeat, winning at all costs.','Reconciliation, forgiveness, moving past conflict.',ARRAY['conflict','defeat','tension','hollow victory'],''),
('swords-06','Six of Swords',6,'swords','/cards/swords-06.jpg','Transition, leaving difficulty behind, moving forward.','Resistance to change, unable to move on.',ARRAY['transition','moving on','relief','travel'],''),
('swords-07','Seven of Swords',7,'swords','/cards/swords-07.jpg','Deception, trickery, strategy, acting alone.','Coming clean, getting caught, conscience.',ARRAY['deception','strategy','stealth','cunning'],''),
('swords-08','Eight of Swords',8,'swords','/cards/swords-08.jpg','Restriction, imprisonment, self-limiting beliefs.','Freedom, releasing restrictions, open eyes.',ARRAY['restriction','imprisonment','powerless','self-sabotage'],''),
('swords-09','Nine of Swords',9,'swords','/cards/swords-09.jpg','Anxiety, worry, fear, nightmares, despair.','Facing fears, inner turmoil releasing.',ARRAY['anxiety','worry','fear','nightmares'],''),
('swords-10','Ten of Swords',10,'swords','/cards/swords-10.jpg','Painful endings, deep wounds, rock bottom, betrayal.','Recovery, resisting an inevitable end.',ARRAY['endings','betrayal','rock bottom','collapse'],''),
('swords-page','Page of Swords',11,'swords','/cards/swords-page.jpg','Curiosity, intellect, new ideas, communication.','Gossip, dishonesty, rash decisions.',ARRAY['intellect','curiosity','communication','alertness'],''),
('swords-knight','Knight of Swords',12,'swords','/cards/swords-knight.jpg','Ambitious, action-oriented, direct, blunt.','Rude, scattered, restless, tactless.',ARRAY['ambition','directness','action','drive'],''),
('swords-queen','Queen of Swords',13,'swords','/cards/swords-queen.jpg','Sharp mind, independent, clear boundaries, direct.','Cold, bitter, cruel, overly critical.',ARRAY['independence','clarity','directness','wisdom'],''),
('swords-king','King of Swords',14,'swords','/cards/swords-king.jpg','Intellectual power, authority, truth, ethical clarity.','Abusive power, manipulation, cruelty.',ARRAY['intellect','authority','truth','ethics'],''),

-- Pentacles
('pentacles-ace','Ace of Pentacles',1,'pentacles','/cards/pentacles-ace.jpg','New financial opportunity, abundance, manifestation.','Lost opportunity, lack of planning, scarcity.',ARRAY['opportunity','abundance','manifestation','prosperity'],''),
('pentacles-02','Two of Pentacles',2,'pentacles','/cards/pentacles-02.jpg','Balance, adaptability, juggling priorities.','Overwhelmed, disorganized, financial strain.',ARRAY['balance','adaptability','juggling','flexibility'],''),
('pentacles-03','Three of Pentacles',3,'pentacles','/cards/pentacles-03.jpg','Teamwork, collaboration, skill, craftsmanship.','Disharmony, misalignment, poor teamwork.',ARRAY['teamwork','skill','collaboration','craftsmanship'],''),
('pentacles-04','Four of Pentacles',4,'pentacles','/cards/pentacles-04.jpg','Stability, security, saving, conservatism.','Greed, materialism, hoarding, financial insecurity.',ARRAY['stability','security','conservatism','possession'],''),
('pentacles-05','Five of Pentacles',5,'pentacles','/cards/pentacles-05.jpg','Hardship, poverty, financial loss, isolation.','Recovery, positive change, improving finances.',ARRAY['hardship','poverty','struggle','isolation'],''),
('pentacles-06','Six of Pentacles',6,'pentacles','/cards/pentacles-06.jpg','Generosity, giving, receiving, sharing wealth.','Debt, strings attached, self-care neglected.',ARRAY['generosity','giving','receiving','balance'],''),
('pentacles-07','Seven of Pentacles',7,'pentacles','/cards/pentacles-07.jpg','Long-term vision, patience, investment, perseverance.','Lack of reward, impatience, poor investment.',ARRAY['patience','investment','perseverance','growth'],''),
('pentacles-08','Eight of Pentacles',8,'pentacles','/cards/pentacles-08.jpg','Diligence, mastery, skill development, dedication.','Perfectionism, no motivation, lack of focus.',ARRAY['diligence','mastery','craftsmanship','practice'],''),
('pentacles-09','Nine of Pentacles',9,'pentacles','/cards/pentacles-09.jpg','Independence, self-sufficiency, luxury, abundance.','Overwork, superficiality, financial dependence.',ARRAY['independence','luxury','self-sufficiency','achievement'],''),
('pentacles-10','Ten of Pentacles',10,'pentacles','/cards/pentacles-10.jpg','Wealth, inheritance, long-term success, family legacy.','Financial failure, instability, family conflict.',ARRAY['legacy','wealth','stability','family'],''),
('pentacles-page','Page of Pentacles',11,'pentacles','/cards/pentacles-page.jpg','Ambition, diligence, learning, opportunity.','Lack of progress, procrastination, immaturity.',ARRAY['ambition','learning','opportunity','diligence'],''),
('pentacles-knight','Knight of Pentacles',12,'pentacles','/cards/pentacles-knight.jpg','Hard work, routine, conservatism, methodical.','Laziness, stagnation, boredom.',ARRAY['hard work','routine','methodical','reliable'],''),
('pentacles-queen','Queen of Pentacles',13,'pentacles','/cards/pentacles-queen.jpg','Nurturing, practical, financially savvy, grounded.','Self-neglect, financial insecurity, imbalance.',ARRAY['nurturing','practical','grounded','resourceful'],''),
('pentacles-king','King of Pentacles',14,'pentacles','/cards/pentacles-king.jpg','Abundance, security, business leadership, discipline.','Corrupt, greedy, excessive materialism.',ARRAY['abundance','leadership','security','discipline'],'')

ON CONFLICT (id) DO NOTHING;
